import math

def verdict(samples, max_p90_ms, max_error_pct):
    if not samples:
        return {"p90": None, "error_pct": None, "passed": False}
    times = sorted(ms for ms, _ in samples)
    p90 = times[math.ceil(0.9 * len(times)) - 1]
    err = round(sum(1 for _, ok in samples if not ok) * 100 / len(samples), 2)
    return {"p90": p90, "error_pct": err, "passed": p90 <= max_p90_ms and err <= max_error_pct}
